from __future__ import annotations

from mirror_models import ApprovedImage, DeploymentRequest, MirrorDriftFinding, MirrorImage, PolicyDecision


def image_key(repository: str, tag: str) -> tuple[str, str]:
    return (repository, tag)


def approved_index(approved_images: list[ApprovedImage]) -> dict[tuple[str, str], ApprovedImage]:
    return {image.key(): image for image in approved_images}


def mirror_index(mirrors: list[MirrorImage]) -> dict[tuple[str, str], MirrorImage]:
    return {image.key(): image for image in mirrors}


def drift_finding(approved: ApprovedImage, mirror: MirrorImage) -> MirrorDriftFinding | None:
    if mirror.matches_digest(approved):
        return None
    return MirrorDriftFinding(
        repository=mirror.internal_repository,
        tag=mirror.tag,
        approved_digest=approved.digest,
        mirrored_digest=mirror.mirrored_digest,
        last_sync_id=mirror.last_sync_id,
    )


def catalog_drift_findings(
    approved_images: list[ApprovedImage],
    mirrors: list[MirrorImage],
) -> list[MirrorDriftFinding]:
    approved_by_key = approved_index(approved_images)
    findings: list[MirrorDriftFinding] = []
    for mirror in mirrors:
        approved = approved_by_key.get(mirror.key())
        if approved is None:
            continue
        finding = drift_finding(approved, mirror)
        if finding is not None:
            findings.append(finding)
    return findings


def make_decision(
    request: DeploymentRequest,
    allowed: bool,
    reason: str,
    approved: ApprovedImage | None = None,
    mirror: MirrorImage | None = None,
) -> dict[str, object]:
    decision = PolicyDecision(
        namespace=request.namespace,
        workload_name=request.workload_name,
        internal_repository=request.internal_repository,
        tag=request.tag,
        allowed=allowed,
        reason=reason,
        approval_ticket=approved.approval_ticket if approved is not None else None,
        risk_owner=approved.risk_owner if approved is not None else None,
        approved_digest=approved.digest if approved is not None else None,
        mirrored_digest=mirror.mirrored_digest if mirror is not None else None,
        last_sync_id=mirror.last_sync_id if mirror is not None else None,
    )
    return decision.as_dict()


def decision_warning(decision: dict[str, object]) -> dict[str, object] | None:
    if decision["allowed"]:
        return None
    return {
        "warning": decision["reason"],
        "namespace": decision["namespace"],
        "workload_name": decision["workload_name"],
        "internal_repository": decision["internal_repository"],
        "tag": decision["tag"],
    }


class MirrorCatalog:
    def __init__(self, approved_images: list[ApprovedImage], mirrors: list[MirrorImage]) -> None:
        self.approved_images = list(approved_images)
        self.mirrors = list(mirrors)
        self._approved_by_key = approved_index(approved_images)
        self._mirrors_by_key = mirror_index(mirrors)

    def approved_for(self, request: DeploymentRequest) -> ApprovedImage | None:
        return self._approved_by_key.get(request.key())

    def mirror_for(self, request: DeploymentRequest) -> MirrorImage | None:
        return self._mirrors_by_key.get(request.key())

    def drift_findings(self) -> list[MirrorDriftFinding]:
        return catalog_drift_findings(self.approved_images, self.mirrors)

    def summary(self) -> dict[str, object]:
        return {
            "approved_image_count": len(self.approved_images),
            "mirror_count": len(self.mirrors),
            "drift_finding_count": len(self.drift_findings()),
        }

