from mirror_catalog import MirrorCatalog, image_key, make_decision
from mirror_models import ApprovedImage, DeploymentRequest, MirrorImage


def _image_key(repository: str, tag: str) -> tuple[str, str]:
    return image_key(repository, tag)


def _decision(
    request: DeploymentRequest,
    allowed: bool,
    reason: str,
    approved: ApprovedImage | None = None,
    mirror: MirrorImage | None = None,
) -> dict[str, object]:
    return make_decision(request, allowed, reason, approved, mirror)


def _audit_warnings(decisions: list[dict[str, object]]) -> list[dict[str, object]]:
    warnings: list[dict[str, object]] = []
    for decision in decisions:
        if decision["allowed"]:
            continue
        warnings.append(
            {
                "warning": decision["reason"],
                "namespace": decision["namespace"],
                "workload_name": decision["workload_name"],
                "internal_repository": decision["internal_repository"],
                "tag": decision["tag"],
            }
        )
    return warnings


def _evaluate_request(catalog: MirrorCatalog, request: DeploymentRequest) -> dict[str, object]:
    approved = catalog.approved_for(request)
    mirror = catalog.mirror_for(request)

    if approved is None:
        return _decision(request, False, "missing_approval", None, mirror)
    if mirror is None:
        return _decision(request, False, "missing_mirror", approved, None)
    return _decision(request, True, "approved", approved, mirror)


def evaluate_disconnected_policy(
    approved_images: list[ApprovedImage],
    mirrors: list[MirrorImage],
    requests: list[DeploymentRequest],
) -> dict[str, object]:
    catalog = MirrorCatalog(approved_images, mirrors)
    decisions: list[dict[str, object]] = []

    for request in requests:
        decisions.append(_evaluate_request(catalog, request))

    return summarize_policy_report(decisions)


def summarize_policy_report(decisions: list[dict[str, object]]) -> dict[str, object]:
    allowed = [decision for decision in decisions if decision["allowed"]]
    blocked = [decision for decision in decisions if not decision["allowed"]]
    warnings = _audit_warnings(decisions)
    return {
        "allowed_count": len(allowed),
        "blocked_count": len(blocked),
        "audit_warning_count": len(blocked),
        "allowed_deployments": allowed,
        "blocked_deployments": blocked,
        "decisions": decisions,
        "audit_warnings": warnings,
    }


class DisconnectedClusterPolicyGate:
    def __init__(self, approved_images: list[ApprovedImage], mirrors: list[MirrorImage]) -> None:
        self.approved_images = list(approved_images)
        self.mirrors = list(mirrors)

    def evaluate(self, requests: list[DeploymentRequest]) -> dict[str, object]:
        return evaluate_disconnected_policy(self.approved_images, self.mirrors, requests)

    def catalog_summary(self) -> dict[str, object]:
        return MirrorCatalog(self.approved_images, self.mirrors).summary()


def explain_mirror_inventory(approved_images: list[ApprovedImage], mirrors: list[MirrorImage]) -> dict[str, object]:
    catalog = MirrorCatalog(approved_images, mirrors)
    return {
        "approved_image_count": len(approved_images),
        "mirror_count": len(mirrors),
        "drift_findings": [finding.as_warning() for finding in catalog.drift_findings()],
